import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { accountsAutomationsList } from '../../generated/api'
import type { PaginatedAccountAutomationListApi } from '../../generated/api.schemas'
import { AccountsEvents } from './constants'

export interface AccountAutomationsLogicProps {
    accountId: string
    instanceId?: string
}

export const AUTOMATIONS_PAGE_SIZE = 10

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountAutomationsLogicValues {
    currentTeamId: number | null // teamLogic
    loadFailed: boolean
    page: number
    runs: PaginatedAccountAutomationListApi | null
    runsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountAutomationsLogicActions {
    loadRuns: (_: void) => void
    loadRunsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRunsSuccess: (
        runs: PaginatedAccountAutomationListApi,
        payload?: void
    ) => {
        runs: PaginatedAccountAutomationListApi
        payload?: void
    }
    setPage: (page: number) => {
        page: number
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface accountAutomationsLogicMeta {
    key: string
}

export type accountAutomationsLogicType = MakeLogicType<
    accountAutomationsLogicValues,
    accountAutomationsLogicActions,
    AccountAutomationsLogicProps,
    accountAutomationsLogicMeta
>

export const accountAutomationsLogic = kea<accountAutomationsLogicType>([
    props({} as AccountAutomationsLogicProps),
    key(({ accountId, instanceId }) => `${accountId}:${instanceId ?? 'default'}`),
    path((key) => ['products', 'customer_analytics', 'accountAutomationsLogic', key]),
    connect({ values: [teamLogic, ['currentTeamId']] }),
    actions({ setPage: (page: number) => ({ page }) }),
    loaders(({ props, values }) => ({
        runs: [
            null as PaginatedAccountAutomationListApi | null,
            {
                loadRuns: async (_: void, breakpoint): Promise<PaginatedAccountAutomationListApi> => {
                    try {
                        return await accountsAutomationsList(String(values.currentTeamId), props.accountId, {
                            limit: AUTOMATIONS_PAGE_SIZE,
                            offset: (values.page - 1) * AUTOMATIONS_PAGE_SIZE,
                        })
                    } finally {
                        breakpoint()
                    }
                },
            },
        ],
    })),
    reducers({
        page: [1, { setPage: (_, { page }) => page }],
        loadFailed: [false, { loadRuns: () => false, loadRunsFailure: () => true }],
    }),
    listeners(({ actions }) => ({
        setPage: () => actions.loadRuns(),
        loadRunsSuccess: ({ runs }) => {
            posthog.capture(AccountsEvents.AutomationsLoaded, { count: runs?.count ?? 0 })
        },
        loadRunsFailure: () => {
            posthog.capture(AccountsEvents.AutomationsLoadFailed)
        },
    })),
    afterMount(({ actions }) => {
        posthog.capture(AccountsEvents.AutomationsViewed)
        actions.loadRuns()
    }),
])
